def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform separator whose color does not occur outside the separator.
    separators = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            separators.append(("row", r, grid[r][0]))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            separators.append(("col", c, grid[0][c]))

    sep = None
    for kind, idx, color in separators:
        outside = (
            [v for r, row in enumerate(grid) if r != idx for v in row]
            if kind == "row"
            else [grid[r][j] for r in range(h) for j in range(w) if j != idx]
        )
        if color not in outside:
            sep = (kind, idx)
            break
    if sep is None:
        kind, idx, _ = separators[0]
        sep = (kind, idx)

    kind, idx = sep
    if kind == "row":
        a, b = grid[:idx], grid[idx + 1:]
        common = set(v for row in a for v in row) & set(v for row in b for v in row)
        background = next(iter(common), 4)
        return [
            [3 if a[r][c] == b[r][c] else background for c in range(w)]
            for r in range(min(len(a), len(b)))
        ]

    a_width, b_width = idx, w - idx - 1
    width = min(a_width, b_width)
    common = (
        {v for r in range(h) for v in grid[r][:a_width]}
        & {v for r in range(h) for v in grid[r][idx + 1:]}
    )
    background = next(iter(common), 4)
    return [
        [3 if grid[r][c] == grid[r][idx + 1 + c] else background
         for c in range(width)]
        for r in range(h)
    ]
